            if (geoAuditIssueResponse.SubjectOption.IsSet)
                if (geoAuditIssueResponse.SubjectOption.Value != null)
                    writer.WriteString("subject", geoAuditIssueResponse.Subject);
                else
                    writer.WriteNull("subject");

            if (geoAuditIssueResponse.SeverityOption.IsSet)
                writer.WriteString("severity", geoAuditIssueResponse.Severity);

            var stateRawValue = GeoAuditIssueResponse.StateEnumToJsonValue(geoAuditIssueResponse.StateOption.Value!.Value);
            writer.WriteString("state", stateRawValue);
            var badgeRawValue = GeoAuditIssueResponse.BadgeEnumToJsonValue(geoAuditIssueResponse.BadgeOption.Value!.Value);
            writer.WriteString("badge", badgeRawValue);
            if (geoAuditIssueResponse.AcceptedOption.IsSet)
                writer.WriteBoolean("accepted", geoAuditIssueResponse.AcceptedOption.Value!.Value);

            if (geoAuditIssueResponse.AcceptedAtOption.IsSet)
                if (geoAuditIssueResponse.AcceptedAtOption.Value != null)
                    writer.WriteString("accepted_at", geoAuditIssueResponse.AcceptedAtOption.Value!.Value.ToString(AcceptedAtFormat));
                else
                    writer.WriteNull("accepted_at");

            if (geoAuditIssueResponse.RegressionCountOption.IsSet)
                writer.WriteNumber("regression_count", geoAuditIssueResponse.RegressionCountOption.Value!.Value);

            if (geoAuditIssueResponse.EvidenceOption.IsSet)
            {
                writer.WritePropertyName("evidence");
                JsonSerializer.Serialize(writer, geoAuditIssueResponse.Evidence, jsonSerializerOptions);
            }
            if (geoAuditIssueResponse.UpdatedAtOption.IsSet)
                writer.WriteString("updated_at", geoAuditIssueResponse.UpdatedAtOption.Value!.Value.ToString(UpdatedAtFormat));

            if (geoAuditIssueResponse.ProjectIdOption.IsSet)
                writer.WriteNumber("project_id", geoAuditIssueResponse.ProjectIdOption.Value!.Value);

            if (geoAuditIssueResponse.RequestIdOption.IsSet)
                writer.WriteString("request_id", geoAuditIssueResponse.RequestId);
        }
    }
}
